.split-section {
    display: flex;
    height: 820px;
    width: 100%;
  }

  .left-half,
  .right-half {
    flex: 1;
    padding: 20px;
    box-sizing: border-box;
    height: 100%;
  }

  .left-half {
    background-color: #F0ECE9;
    color: #000;
  }

  .right-half {
    background-color: #691BE4;
    color: #fff;
  }

  @media (max-width: 768px) {
    .split-section {
      flex-direction: column;
      height: auto;
    }

    .left-half,
    .right-half {
      width: 100%;
      height: auto;
    }
  }
